(function(){
'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'PKR '+Number(n||0).toLocaleString('en-PK',{maximumFractionDigits:2}),date=s=>new Date(s).toLocaleDateString('en-GB');
function create(api){
 let access={},identity=null,tab='overview',page=1,refPage=1,orders={rows:[],total:0},generation=0;
 const invite=code=>{const u=new URL(location.origin+location.pathname);u.searchParams.set('vendor',code);u.hash='vendor-register';return u.href};
 const metric=(label,value)=>`<div class="vendor-metric"><span>${label}</span><strong>${value}</strong></div>`;
 function setup(){
  const registration=document.createElement('section');registration.id='page-vendor-register';registration.className='page';registration.innerHTML=`<div class="vendor-registration"><header class="vendor-heading"><div><small>SELL ON MARKET IS ONLINE</small><h1>Register your store</h1><p>Create a separate seller account. Verify your email, submit your business details, then accept the company agreement.</p></div></header><form id="vendorSignupForm" class="vendor-signup form"><div class="row"><label>Your full name<input name="fullName" required maxlength="120" autocomplete="name"></label><label>Phone<input name="phone" required type="tel" autocomplete="tel"></label></div><div class="row"><label>Email<input name="email" required type="email" autocomplete="email"></label><label>Password<input name="password" required type="password" minlength="8" autocomplete="new-password"></label></div><div class="row"><label>Country<select name="country" required>${api.countryOptions('PK')}</select></label><label>Gender<select name="gender" required><option value="">Select</option><option value="male">Male</option><option value="female">Female</option></select></label></div><label>Vendor invitation code<input name="invitation" required autocomplete="off" placeholder="MIO member ID"></label><label class="vendor-consent"><input type="checkbox" name="consent" required> I accept the <a href="#terms">terms and conditions</a>.</label><button class="btn primary" type="submit">Create seller account</button><p role="status"></p><p>Already registered? <button type="button" class="btn small" data-page="login">Sign in</button></p></form><div id="vendorApplicationHost"></div></div>`;
  $('main-content').append(registration);
  const application=$('sellerForm').closest('.card');$('vendorApplicationHost').append(application);application.hidden=true;
  $('sellerIntroducer').required=false;$('sellerIntroducer').removeAttribute('pattern');$('sellerReferralField').hidden=true;$('sellerExistingAccount').hidden=true;
  $('page-sell').replaceChildren();$('page-sell').innerHTML='<div id="vendorReferralDashboard"></div>';
  const seller=$('page-seller'),settlement=document.createElement('div');settlement.id='vendorSettlementPanel';settlement.className='vendor-panel';
  // Keep the existing payout form and its handlers intact.
  for(const card of [...seller.querySelectorAll(':scope>.card')])settlement.append(card);
  const brand=$('sellerBrand'),summary=$('sellerSummary');seller.replaceChildren();
  seller.innerHTML=`<div class="vendor-portal"><header class="vendor-portal-bar"><button type="button" class="vendor-menu-toggle" aria-label="Toggle seller menu" aria-expanded="false">☰</button><div><small>SELLER PORTAL</small><h1 id="vendorStoreName">Your store</h1></div><span id="vendorStoreState" class="vendor-state"></span></header><div class="vendor-portal-layout"><nav class="vendor-portal-nav" aria-label="Seller navigation">${[['overview','Overview'],['products','Products'],['orders','Orders'],['inventory','Inventory'],['settlements','Sales & settlements'],['store','Store details']].map(([key,title])=>`<button type="button" data-vendor-tab="${key}">${title}</button>`).join('')}<button type="button" data-page="support">Support</button></nav><div class="vendor-portal-main"><div class="vendor-store-selector"><label for="sellerBrand">Store</label></div><div id="vendorPending" hidden></div><div id="vendorOverview" class="vendor-panel"></div><div id="vendorProductsPanel" class="vendor-panel"></div><div id="vendorOrdersPanel" class="vendor-panel"></div><div id="vendorStorePanel" class="vendor-panel"></div></div></div></div>`;
  seller.querySelector('.vendor-store-selector').append(brand);$('vendorProductsPanel').append($('sellerProducts')||api.productSection);seller.querySelector('.vendor-portal-main').append(settlement);summary.hidden=true;settlement.prepend(summary);
  seller.addEventListener('click',e=>{const button=e.target.closest('[data-vendor-tab]');if(button){show(button.dataset.vendorTab);if(button.dataset.newProduct)api.newProduct();return}if(e.target.closest('.vendor-menu-toggle')){const open=seller.classList.toggle('vendor-menu-open');e.target.closest('button').setAttribute('aria-expanded',String(open))}const pager=e.target.closest('[data-vendor-page]');if(pager){page+=Number(pager.dataset.vendorPage);refresh().catch(api.error)}const detail=e.target.closest('[data-vendor-order]');if(detail){const panel=$(detail.dataset.vendorOrder);panel.hidden=!panel.hidden;detail.setAttribute('aria-expanded',String(!panel.hidden))}});
  $('vendorSignupForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('[type=submit]'),status=f.querySelector('[role=status]');if(b.disabled)return;b.disabled=true;status.textContent='Creating your seller account…';try{const r=await api.db.auth.signUp({email:f.elements.email.value.trim(),password:f.elements.password.value,options:{emailRedirectTo:location.origin+location.pathname+'#vendor-register',data:{registration_type:'vendor',vendor_invitation:f.elements.invitation.value.trim().toUpperCase(),full_name:f.elements.fullName.value.trim(),phone:f.elements.phone.value.trim(),country_code:f.elements.country.value,gender:f.elements.gender.value,terms_accepted:f.elements.consent.checked?'true':'false'}}});if(r.error)throw r.error;f.elements.password.value='';status.textContent='Check your email to verify your seller account, then sign in to complete the application.';if(r.data?.session)await api.signedUp(r.data.session)}catch(error){status.textContent=error.message}finally{b.disabled=false}};
 }
 async function identify(session){identity=session?.user.id||null;const token=++generation;access={};document.body.classList.remove('vendor-only');if(!identity)return access;const r=await api.db.rpc('my_vendor_access');if(r.error)throw r.error;if(token!==generation)return {};access=r.data||{};document.body.classList.toggle('vendor-only',!!access.vendor_only);return access}
 function show(next='overview'){tab=next;const active=next==='inventory'?'products':next;for(const [key,id] of Object.entries({overview:'vendorOverview',products:'vendorProductsPanel',orders:'vendorOrdersPanel',settlements:'vendorSettlementPanel',store:'vendorStorePanel'}))$(id).hidden=key!==active;$('page-seller').querySelectorAll('[data-vendor-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.vendorTab===next);b.setAttribute('aria-current',b.dataset.vendorTab===next?'page':'false')});$('page-seller').classList.remove('vendor-menu-open');$('page-seller').querySelector('.vendor-menu-toggle').setAttribute('aria-expanded','false');if(next==='inventory')api.inventory()}
 async function registration(){const signed=!!api.session(),allowed=api.registrationOpen();$('vendorSignupForm').hidden=signed||!allowed;const f=$('vendorSignupForm');f.elements.invitation.value=new URLSearchParams(location.search).get('vendor')||sessionStorage.getItem('mio-vendor-invite')||'';const host=$('vendorApplicationHost');host.firstElementChild.hidden=!signed||!access.vendor_only||!access.email_verified||!allowed;let note=$('vendorRegistrationNote');if(!note){note=document.createElement('p');note.id='vendorRegistrationNote';host.before(note)}note.textContent=!allowed?'New vendor applications are currently closed.':signed&&!access.vendor_only?'You are signed in to a member account. Share your vendor invitation with the business owner, who should register using their own email.':signed&&!access.email_verified?'Verify your email before submitting your business details.':'';if(signed&&access.vendor_only){if(access.identity){$('sellerPhone').value||=access.identity.phone;$('sellerEmail').value||=api.session().user.email||'';$('sellerCountry').value=access.identity.country_code}await api.agreement()}}
 function orderTable(rows,scope='overview'){return `<div class="vendor-table-wrap"><table><thead><tr><th>Order</th><th>Date</th><th>Amount</th><th>Status</th><th>Details</th></tr></thead><tbody>${rows.map((o,i)=>`<tr><td>${esc(o.order_code)}</td><td>${date(o.created_at)}</td><td>${money(o.amount)}</td><td><span class="vendor-pill ${o.status==='delivered'?'done':''}">${esc(o.status)}</span></td><td><button class="btn small" type="button" data-vendor-order="vendorOrder-${scope}-${i}" aria-expanded="false">View</button></td></tr><tr id="vendorOrder-${scope}-${i}" hidden><td colspan="5"><strong>Payment: ${esc(o.payment_status)}</strong><ul>${(o.items||[]).map(p=>`<li>${esc(p.name)} × ${p.quantity} · ${money(p.amount)}</li>`).join('')}</ul></td></tr>`).join('')||'<tr><td colspan="5">Your orders will appear here.</td></tr>'}</tbody></table></div>`}
 async function refresh(){const token=generation;await api.loadBrands();if(token!==generation)return;const v=api.currentVendor(),root=$('page-seller');$('vendorStoreName').textContent=v?.business_name||'Seller application';$('vendorStoreState').textContent=v?'Approved vendor':'Awaiting approval';$('vendorPending').hidden=!!v;root.querySelector('.vendor-store-selector').hidden=!v||$('sellerBrand').options.length<=1;root.querySelector('.vendor-portal-nav').hidden=!v;if(!v){show('pending');$('vendorPending').innerHTML='<h2>Complete your seller application</h2><p>Business details and the company agreement are required before your store is approved.</p><button class="btn primary" data-page="vendor-register">View application</button>';return}
  const [r,s]=await Promise.all([api.db.rpc('seller_portal_orders',{p_vendor:v.id,p_page:page}),api.db.rpc('my_brand_summary',{p_vendor_id:v.id})]);if(r.error||s.error)throw r.error||s.error;if(token!==generation)return;orders=r.data||{rows:[],total:0};const products=api.products(),stats=s.data||{},available=Number(stats.income_pkr||0)-Number(stats.reserved_pkr||0)-Number(stats.paid_pkr||0);
  $('vendorOverview').innerHTML=`<div class="vendor-section-title"><h2>Store overview</h2><span>All time</span></div><div class="vendor-metrics">${metric('Net sales',money(stats.income_pkr))}${metric('Orders',orders.total)}${metric('Live products',products.filter(p=>p.status==='approved').length)}${metric('Available payout',money(available))}</div><div class="vendor-quick-actions"><button class="btn primary" data-vendor-tab="products" data-new-product="1">＋ Add product</button><button class="btn" data-vendor-tab="inventory">Manage inventory</button></div><div class="vendor-attention">${products.filter(p=>p.status==='pending').length} listings awaiting review</div><div class="vendor-section-title"><h2>Recent orders</h2><button class="btn small" data-vendor-tab="orders">View orders →</button></div>${orderTable(orders.rows.slice(0,5))}<div class="vendor-section-title"><h2>Products</h2><button class="btn small" data-vendor-tab="products">View products →</button></div><div class="vendor-table-wrap"><table><thead><tr><th>Product</th><th>Status</th><th>Stock</th><th>Action</th></tr></thead><tbody>${products.slice(0,5).map(p=>`<tr><td><div class="vendor-product-name">${api.safeImage(p.image_url)?`<img src="${esc(api.safeImage(p.image_url))}" alt="">`:''}<b>${esc(p.name)}</b></div></td><td><span class="vendor-pill">${esc(p.status)}</span></td><td>${p.stock_quantity}</td><td><button class="btn small edit-listing" data-id="${esc(p.id)}">Edit</button></td></tr>`).join('')||'<tr><td colspan="4">Add your first product to get started.</td></tr>'}</tbody></table></div>`;
  $('vendorOrdersPanel').innerHTML=`<h2>Orders</h2>${orderTable(orders.rows,'all')}<div class="vendor-pagination"><button class="btn small" data-vendor-page="-1" ${page===1?'disabled':''}>Previous</button><span>Page ${page} · ${orders.total} orders</span><button class="btn small" data-vendor-page="1" ${page*50>=orders.total?'disabled':''}>Next</button></div>`;
  $('vendorStorePanel').innerHTML=`<h2>Store details</h2><dl class="vendor-store-details"><dt>Business</dt><dd>${esc(v.business_name)}</dd><dt>Contact email</dt><dd>${esc(v.contact_email||'—')}</dd><dt>Contact phone</dt><dd>${esc(v.contact_phone||'—')}</dd><dt>Agreed commission</dt><dd>${(Number(v.commission_rate||0)*100).toFixed(2)}%</dd><dt>Status</dt><dd>${esc(v.status)}</dd></dl><p>Contact support to request changes to your verified business details or agreement.</p><button class="btn" data-page="support">Contact support</button>`;show(tab);
 }
 async function referrals(){const token=generation,host=$('vendorReferralDashboard'),profile=api.profile();if(!profile){host.innerHTML='<h1>Sell with us</h1><p>Sign in to your member account to invite vendors.</p><button class="btn primary" data-page="login">Sign in</button>';return}const r=await api.db.rpc('my_vendor_referrals',{p_page:refPage});if(r.error)throw r.error;if(token!==generation)return;const d=r.data||{},rows=d.rows||[],history=d.history||[],url=invite(profile.member_code);
  host.innerHTML=`<header class="vendor-heading"><div><small>SELL WITH US</small><h1>Your vendor network</h1><p>Invite businesses and track your vendor commission.</p></div></header><div class="vendor-metrics">${metric('Registered vendors',d.total||0)}${metric('Vendor commission',Number(d.credited||0).toFixed(2)+' MIO')}${metric('Pending commission',Number(d.pending||0).toFixed(2)+' MIO')}</div><section class="vendor-invitation"><div><h2>Vendor registration link</h2><p>The business owner registers a separate seller account. Company approval is required.</p><input readonly aria-label="Vendor registration link" value="${esc(url)}"></div><button class="btn primary copy-code" data-copy="${esc(url)}">Copy link</button></section><h2>Registered vendors</h2><div class="vendor-table-wrap"><table><thead><tr><th>Vendor</th><th>Registered</th><th>Status</th><th>Commission</th></tr></thead><tbody>${rows.map(v=>`<tr><td>${esc(v.business_name)}</td><td>${date(v.created_at)}</td><td><span class="vendor-pill">${esc(v.status)}</span></td><td>${Number(v.commission).toFixed(2)} MIO</td></tr>`).join('')||'<tr><td colspan="4">Share your link to invite your first vendor.</td></tr>'}</tbody></table></div><h2>Vendor commission history</h2><div class="vendor-table-wrap"><table><thead><tr><th>Date</th><th>Vendor / order</th><th>Status</th><th>Amount</th></tr></thead><tbody>${history.map(r=>`<tr><td>${date(r.created_at)}</td><td>${esc(r.business_name)}<small>${esc(r.order_code)}</small></td><td>${esc(({posted:'Credited',held_activation:'Awaiting activation',pending_delivery:'Awaiting delivery',cancelled:'Cancelled',company_leftover:'Not payable'})[r.status]||r.status)}</td><td>${Number(r.amount).toFixed(2)} MIO</td></tr>`).join('')||'<tr><td colspan="4">Vendor commission is recorded after qualifying sales.</td></tr>'}</tbody></table></div><div class="vendor-pagination"><button class="btn small" data-referral-page="-1" ${refPage===1?'disabled':''}>Previous</button><span>Page ${refPage} · 50 rows per list</span><button class="btn small" data-referral-page="1" ${refPage*50>=Math.max(d.total||0,d.history_total||0)?'disabled':''}>Next</button></div>`;
  host.querySelectorAll('[data-referral-page]').forEach(b=>b.onclick=()=>{refPage+=Number(b.dataset.referralPage);referrals().catch(api.error)});
 }
 function clear(){generation++;access={};identity=null;tab='overview';page=refPage=1;document.body.classList.remove('vendor-only','seller-portal-active');['vendorReferralDashboard','vendorOverview','vendorOrdersPanel','vendorStorePanel','sellerAgreement'].forEach(id=>$(id)?.replaceChildren());$('vendorSignupForm')?.reset();$('sellerForm')?.reset();if($('vendorApplicationHost')?.firstElementChild)$('vendorApplicationHost').firstElementChild.hidden=true}
 // Capture and move existing controls rather than replacing their event handlers.
 api.productSection=$('sellerProducts');api.productSection.remove();setup();
 return {identify,registration,refresh,referrals,show,clear,invite,get access(){return access}};
}
window.MioVendorPortal={create};
})();
